    // Publications: publications, text with quotes.
    'publications.noPeerIsConnectedSo2': 'No hay ningún par conectado, así que “Recuperar de los pares” no puede obtener el contenido que falta. Conéctese con uno desde {peers}.',
    'publications.thisIsACorrelationOf2': 'Esta es una correlación de hechos registrados de forma independiente según un anchorId explícito, no un veredicto. Vea “Evidencia histórica de anclajes en Bitcoin” arriba para el desglose completo, observación por observación, de este mismo anchorId.',
    'publications.thisIsAReadOnly': 'Esta es una vista de solo lectura del archivo de arriba: no cambia nada del Archivo de observaciones que se mostró antes en esta página. Use “Importar archivo” arriba si quiere que este archivo lo reemplace.',
    'publications.whatReplacingTheCurrentArchive': 'Lo que cambiaría reemplazar el archivo actual por el archivo externo de arriba: el archivo actual queda exactamente como está hasta que se haga clic explícitamente en “Reemplazar el archivo actual” abajo.',
    'publications.replacingRestampsEveryFactIn': 'Reemplazar vuelve a marcar cada hecho del archivo externo de arriba como IMPORTADO (0.8.83), por lo que la huella actual resultante será distinta de la “Huella externa” que se muestra arriba, aunque las observaciones subyacentes sean idénticas.',
    'publications.localFactsWereObservedBy': 'Los hechos locales los observó directamente esta réplica. Los hechos importados entraron a este archivo mediante una importación anterior con “Reemplazar el archivo actual”. Ninguno es más fiable que el otro: esto solo indica de dónde viene cada hecho.',
    'publications.anExplicitDurableRecordThat2': 'Un registro explícito y duradero de que una publicación hace referencia a otra; nunca se deduce de contenidos, marcas de tiempo o autores que coinciden. Ambas publicaciones ya deben tener una identidad duradera arriba; una referencia nunca es una clasificación como “bifurcación”, solo un hecho simple y atribuible: esta publicación apunta a aquella.',
    'publications.nothingHereIsSavedAnywhere': 'Nada de esto se guarda en ningún lugar. Esta configuración vive solo en la memoria de esta página durante esta sesión de navegación, y se descarta en cuanto la página se recarga o se hace clic en “Borrar configuración”.',
    'publications.thisReplicaDoesNotCurrently': 'Esta réplica no tiene actualmente un Snapshot válido. Elija una fuente abajo (“Importar Snapshot”, “Materializar Snapshot” de una ubicación u “Obtener Snapshot del par” de un par) para intentarlo de nuevo.',

    // Publications: leaderboardHubView, text with quotes.
    'leaderboardHubView.aBadgePresentationOfThe': 'Una presentación como insignias de los logros que este editor ya obtuvo, en todas las publicaciones que reivindicó de forma explícita: nunca un logro nuevo, y nunca una puntuación, una posición ni una entrada de la clasificación. Algunos logros (los derivados de referencias) todavía no tienen presentación como insignia y solo aparecen en la tarjeta “Perfil de logros del editor” de arriba.',

    // Publications: publisherLeaderboardSnapshotClaimAuthoringView, text with quotes.
    'publisherLeaderboardSnapshotClaimAuthoringView.authorAndExportASigned': 'Cree y exporte una declaración firmada sobre la instantánea actual de la clasificación de SU PROPIA réplica: exactamente el artefacto de evidencia que el campo “Evidencia del par” del Espacio de conciliación le pide pegar a un par. Generar, firmar y exportar son tres acciones separadas y explícitas; nada en esta página se ejecuta automáticamente.',
    'publisherLeaderboardSnapshotClaimAuthoringView.pasteThisIntoAPeer': 'Pegue esto en el campo “Evidencia del par” del Espacio de conciliación de un par, o envíele el archivo descargado.',

    // Publications: reconciliationCandidateLeaderboardView, text with quotes.
    'reconciliationCandidateLeaderboardView.noPeerArchiveSuppliedYet': 'Todavía no se proporcionó ningún archivo de par: todos los conteos de abajo son Solo en origen hasta que pegue uno. Pegue el archivo exportado por la réplica de un par (Exportar archivo, en la página Publicaciones) y haga clic en “Usar como archivo del par”.',

    // Publications: reconciliationWorkspaceView, text with quotes.
    'reconciliationWorkspaceView.reconcileThisReplicaSOwn': 'Concilie el archivo local propio de esta réplica con una pieza de evidencia de un par, de forma explícita. Nada en esta página se ejecuta automáticamente: la conciliación solo ocurre cuando hace clic en “Conciliar”, abajo.',

